MARKER_RE = re.compile(r"((?:ADDED|GENERATED)-LINE-RATIONALE)\s+([0-9a-f]{16}:[0-9]+):\s*(\S.*?)(?:\s*(?:-->|\*/))?$")


def is_rationale_comment_line(line: str) -> bool:
    stripped = line.strip()
    is_comment = stripped.startswith(("# ", "// ", "/* ", "<!-- "))
    return is_comment and (MARKER in stripped or GENERATED_MARKER in stripped)


@dataclasses.dataclass(frozen=True)
class LineInfo:
    number: int
    text: str
    context: str
    group: tuple[str, int]


@dataclasses.dataclass(frozen=True)
class Target:
    path: str
    line: LineInfo
    key: str
    explanation: str


def run_git(root: pathlib.Path, *args: str) -> str:
    result = subprocess.run(
        ["git", *args], cwd=root, check=False, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    if result.returncode:
        raise RuntimeError(result.stderr.strip() or f"git {' '.join(args)} failed")
    return result.stdout


def fnv1a64(value: str) -> str:
    digest = 0xCBF29CE484222325
    for byte in value.encode("utf-8"):
        digest ^= byte
        digest = (digest * 0x100000001B3) & 0xFFFFFFFFFFFFFFFF
    return f"{digest:016x}"


def leading_spaces(line: str) -> int:
    return len(line) - len(line.lstrip(" "))


def workflow_contexts(lines: list[str]) -> list[LineInfo]:
    result: list[LineInfo] = []
    scalar_indent: int | None = None
    scalar_start = 0
    scalar_shell = "bash"
    nested: tuple[str, int] | None = None
    for index, line in enumerate(lines, 1):
        stripped = line.strip()
        indent = leading_spaces(line)
        if scalar_indent is not None and stripped and indent < scalar_indent:
            scalar_indent = None
            nested = None
        if scalar_indent is None:
            context = "yaml"
            group = ("yaml", 0)
            if re.match(r"^\s*run:\s*\|[-+]?\s*$", line):
                scalar_start = index
                scalar_indent = indent + 2
                nearby = "\n".join(lines[max(0, index - 8) : index])
                scalar_shell = "powershell" if re.search(r"^\s*shell:\s*pwsh\s*$", nearby, re.MULTILINE) else "bash"
        else:
            context = scalar_shell
            group = (scalar_shell, scalar_start)
            if nested is not None:
                nested_context, opener = nested
                if (nested_context == "csharp" and stripped == "'@") or (nested_context == "python" and stripped == "PY"):
                    context = scalar_shell
                    group = (scalar_shell, scalar_start)
                    nested = None
                else:
                    context = nested_context
                    group = (nested_context, opener)
            elif scalar_shell == "powershell" and stripped.endswith("@'"):
                nested = ("csharp", index)
            elif scalar_shell == "bash" and re.search(r"<<'?PY'?\s*$", stripped):
                nested = ("python", index)
        result.append(LineInfo(index, line, context, group))
    return result


def html_contexts(lines: list[str]) -> list[LineInfo]:
    result: list[LineInfo] = []
    in_style = False
    style_start = 0
    for index, line in enumerate(lines, 1):
        context = "css" if in_style else "html"
        group = (context, style_start if in_style else 0)
        result.append(LineInfo(index, line, context, group))
        if re.search(r"<style(?:\s[^>]*)?>", line, re.IGNORECASE):
            in_style = True
            style_start = index
        if re.search(r"</style\s*>", line, re.IGNORECASE):
            in_style = False
    return result


def ordinary_contexts(path: str, lines: list[str]) -> list[LineInfo]:
    suffix = pathlib.Path(path).suffix.lower()
    context = {
        ".rs": "rust",
        ".py": "python",
        ".cpp": "cpp",
        ".h": "cpp",
        ".rc": "rc",
        ".css": "css",
        ".toml": "toml",
        ".sh": "bash",
        ".ps1": "powershell",
        ".desktop": "ini",
        "": "bash",
    }[suffix]
    return [LineInfo(index, line, context, (context, 0)) for index, line in enumerate(lines, 1)]


def contexts(path: str, lines: list[str]) -> list[LineInfo]:
    suffix = pathlib.Path(path).suffix.lower()
    if suffix in {".yml", ".yaml"}:
        return workflow_contexts(lines)
    if suffix == ".html":
        return html_contexts(lines)
    return ordinary_contexts(path, lines)


def comment_only_flags(infos: list[LineInfo]) -> list[bool]:
    flags: list[bool] = []
    block_context: str | None = None
    for info in infos:
        stripped = info.text.strip()
        if is_rationale_comment_line(stripped):
            flags.append(True)
            continue
        if not stripped:
            flags.append(False)
            continue
        if block_context == info.context:
            flags.append(True)
            if "*/" in stripped or "-->" in stripped:
                block_context = None
            continue
        if info.context in {"rust", "cpp", "csharp", "rc"} and stripped.startswith("//"):
            flags.append(True)
        elif info.context in {"python", "yaml", "bash", "powershell", "toml", "ini"} and stripped.startswith("#"):
            flags.append(True)
        elif info.context in {"rust", "cpp", "csharp", "rc", "css"} and stripped.startswith("/*"):
            flags.append(True)
            if "*/" not in stripped:
                block_context = info.context
        elif info.context == "html" and stripped.startswith("<!--"):
            flags.append(True)
            if "-->" not in stripped:
                block_context = info.context
        else:
            flags.append(False)
    return flags


def changed_line_numbers(root: pathlib.Path, path: str, tracked: bool) -> set[int]:
    if not tracked:
        return set(range(1, len((root / path).read_text(encoding="utf-8").splitlines()) + 1))
    diff = run_git(root, "diff", "--unified=0", "--no-color", BASE, "--", path)
    numbers: set[int] = set()
    new_line = 0
    for line in diff.splitlines():
        match = re.match(r"^@@ -(?:\d+)(?:,\d+)? \+(\d+)(?:,(\d+))? @@", line)
        if match:
            new_line = int(match.group(1))
        elif line.startswith("+") and not line.startswith("+++"):
            numbers.add(new_line)
            new_line += 1
        elif line.startswith("-") and not line.startswith("---"):
            continue
        elif line.startswith(" "):
            new_line += 1
    return numbers


def audited_path(path: str) -> bool:
    return pathlib.Path(path).suffix.lower() in EXTENSIONS or path in SPECIAL_CODE_PATHS


def source_paths(root: pathlib.Path) -> list[tuple[str, bool]]:
    tracked = {
        line for line in run_git(root, "diff", "--name-only", "--diff-filter=ACMRTUXB", BASE).splitlines() if audited_path(line)
    }
    untracked = {
        line
        for line in run_git(root, "ls-files", "--others", "--exclude-standard").splitlines()
        if audited_path(line)
    }
    return [(path, True) for path in sorted(tracked)] + [(path, False) for path in sorted(untracked - tracked)]


def file_purpose(path: str) -> str:
    if "/tests/" in path or path.endswith("/tests.rs") or pathlib.Path(path).stem.endswith("test"):
        return "the regression suite can pin the refreshed behavior before release"
    if path.startswith(".github/workflows/"):
        return "the release automation exercises the same deterministic path on hosted runners"
    if path.startswith("installer/windows/"):
        return "the native Windows installer remains accessible, deterministic, and warning-clean"
    if path.startswith("packaging/"):
        return "packaging produces reproducible artifacts without platform-dependent fallbacks"
    if path.startswith("xtask/") or path.startswith("scripts/"):
        return "repository checks can reproduce and audit generated launcher assets"
    if "redrob-launcher-web" in path:
        return "the web loading surface matches the native launcher's design-system state"
    if "ui-egui" in path:
        return "the shared egui interface renders and responds consistently on desktop and web"
    if "redrob-launcher/src" in path:
        return "the desktop shell integrates refreshed UI behavior without changing platform contracts"
    if path.endswith("Cargo.toml"):
        return "Cargo resolves the intended feature and dependency graph for this launcher build"
    return "the refreshed launcher keeps its behavior explicit and reproducible across supported platforms"


def line_focus(info: LineInfo, infos: list[LineInfo]) -> str:
    ignored = {
        "pub", "const", "let", "mut", "fn", "def", "class", "struct", "enum", "impl", "self",
        "return", "if", "else", "for", "while", "match", "Some", "None", "true", "false", "use",
        "from", "import", "run", "name", "with", "this", "static", "void", "auto", "constexpr",
    }
    candidates = [info]
    for distance in range(1, 8):
        before = info.number - distance - 1
        after = info.number + distance - 1
        if before >= 0:
            candidates.append(infos[before])
        if after < len(infos):
            candidates.append(infos[after])
    for candidate in candidates:
        if is_rationale_comment_line(candidate.text):
            continue
        words = [word for word in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", candidate.text) if word not in ignored]
        if words:
            return " / ".join(words[:3])
    return pathlib.Path(info.context).stem or "local operation"


def semantic_owner(path: str, info: LineInfo, infos: list[LineInfo]) -> str:
    patterns = [
        re.compile(r"(?:fn|def|class|struct|enum|mod|function)\s+([A-Za-z_][A-Za-z0-9_-]*)"),
        re.compile(r"(?:HRESULT|LRESULT|DWORD|UINT|BOOL|bool|void|int|static\s+\w+)\s+([A-Za-z_][A-Za-z0-9_]*)\s*\("),
        re.compile(r"-\s+name:\s*([^#]+)"),
        re.compile(r"^\s*\[([^]]+)\]"),
    ]
    for candidate in reversed(infos[: info.number]):
        if is_rationale_comment_line(candidate.text):
            continue
        for pattern in patterns:
            match = pattern.search(candidate.text)
            if match:
                owner = " ".join(match.group(1).strip().split())
                return owner[:72]
    return pathlib.Path(path).stem.replace("_", "-")


def nearby_constraint(info: LineInfo, infos: list[LineInfo]) -> str | None:
    for candidate in reversed(infos[max(0, info.number - 13) : info.number - 1]):
        stripped = candidate.text.strip()
        if is_rationale_comment_line(stripped):
            continue
        if stripped.startswith(("//", "#", "<!--", "/*", "*")):
            note = re.sub(r"^(?://+|#+|/\*+|\*+|<!--)\s*", "", stripped)
            note = re.sub(r"(?:\*/|-->)$", "", note).strip()
            if note and not note.startswith(("Generated by", "the values are")):
                return note[:140].rstrip(".")
        if stripped:
            break
    return None


def explain(path: str, info: LineInfo, infos: list[LineInfo]) -> str:
    stripped = info.text.strip()
    if path == "scripts/check_added_line_comments.py":
        return "Preserves exact fixed-base rationale accounting so release-monotonicity and supply-chain-determinism changes remain literally audited."
    if path == "xtask/src/tokens.rs":
        return "Pins and verifies the design-system package while bounding archive inputs so token generation remains supply-chain deterministic."
    if path == "xtask/src/main.rs":
        return "Documents the integrity-pinned token workflow so developers and CI use the same supply-chain-deterministic source."
    focus = line_focus(info, infos)
    owner = semantic_owner(path, info, infos)
    purpose = file_purpose(path)
    constraint = nearby_constraint(info, infos)
    assignment = re.match(r"(?:let\s+(?:mut\s+)?|const\s+|constexpr\s+|\$)?([A-Za-z_][A-Za-z0-9_]*)[^=]*=", stripped)
    declaration = re.search(r"(?:fn|def|class|struct|enum|mod|function)\s+([A-Za-z_][A-Za-z0-9_-]*)", stripped)
    key = re.match(r"[-\s]*([A-Za-z_][A-Za-z0-9_.-]*)\s*[:=]", stripped)
    call = re.search(r"([A-Za-z_][A-Za-z0-9_:.-]*)\s*[!(]", stripped)
    if constraint:
        return f"Supports `{owner}` while preserving the nearby constraint: {constraint}."
    if stripped.startswith(("use ", "import ", "from ", "#include")):
        return f"Gives `{owner}` direct access to `{focus}` instead of relying on an implicit platform facility."
    if declaration:
        return f"Isolates `{declaration.group(1)}` as the owner of this behavior so callers can use and test it without duplicating policy."
    if assignment:
        return f"Freezes `{assignment.group(1)}` for `{owner}` so every later calculation in this path observes the same input."
    if info.context in {"yaml", "toml", "ini"} and key:
        return f"Pins `{key.group(1)}` for `{owner}` so automation does not inherit a runner or tool default."
    if stripped.startswith(("assert", "Expect ", "throw ", "raise ")):
        return f"Makes `{owner}` fail visibly when `{focus}` violates the behavior this path promises."
    if stripped.startswith(("if ", "if(", "if (", "elif ", "else", "match ", "switch ", "case ")):
        return f"Prevents `{owner}` from applying its side effect outside the `{focus}` state."
    if stripped.startswith(("for ", "foreach ", "while ", "loop ")):
        return f"Applies `{owner}` consistently to every `{focus}` item rather than handling only the first match."
    if stripped.startswith(("return ", "return;", "break", "continue")):
        return f"Stops `{owner}` at the `{focus}` outcome so no later branch can overwrite that result."
    if stripped.startswith(("#[", "[", "@")):
        return f"Declares the `{focus}` contract on `{owner}` so the compiler or runner applies it before execution."
    if stripped.startswith(("#define", "#pragma", "#if", "#endif")):
        return f"Keeps `{owner}` on the `{focus}` compile-time path required by the supported native targets."
    if stripped.startswith(("<", "</", "<!")):
        return f"Keeps `{focus}` inside the `{owner}` document region so loading-page structure and styling stay scoped."
    if info.context == "css":
        return f"Limits the `{focus}` visual role to `{owner}` so generated tokens do not leak into unrelated elements."
    if stripped in {"{", "}", "};", "[", "]", "(", ")", ");", "];", ","}:
        return f"Bounds the `{owner}` implementation here so `{focus}` cannot leak into the adjacent declaration or control path."
    if stripped.endswith(","):
        return f"Keeps `{focus}` in `{owner}`'s API-defined order so positional values retain their intended meaning."
    if call:
        return f"Delegates `{owner}`'s `{focus}` work to `{call.group(1)}` so existing state and error handling remain centralized."
    return f"Makes `{focus}` an explicit part of `{owner}` because {purpose}."


def collect_targets(root: pathlib.Path) -> tuple[list[Target], dict[str, list[LineInfo]]]:
    targets: list[Target] = []
    files: dict[str, list[LineInfo]] = {}
    occurrences: collections.Counter[tuple[str, str]] = collections.Counter()
    for path, tracked in source_paths(root):
        lines = (root / path).read_text(encoding="utf-8").splitlines()
        infos = contexts(path, lines)
        files[path] = infos
        flags = comment_only_flags(infos)
        changed = changed_line_numbers(root, path, tracked)
        for info, is_comment in zip(infos, flags):
            if not info.text.strip() or is_comment:
                continue
            digest = fnv1a64(f"{path}\0{info.text}")
            occurrences[(path, digest)] += 1
            if info.number not in changed:
                continue
            key = f"{digest}:{occurrences[(path, digest)]}"
            targets.append(Target(path, info, key, explain(path, info, infos)))
    return targets, files


def marker_text(context: str, target: Target) -> str:
    explanation = target.explanation.replace("*/", "* /").replace("--", "-")
    body = f"{MARKER} {target.key}: {explanation}"
    if context in {"rust", "cpp", "csharp", "rc"}:
        return f"// {body}"
    if context in {"css"}:
        return f"/* {body} */"
    if context == "html":
        return f"<!-- {body} -->"
    return f"# {body}"


def strip_markers(root: pathlib.Path) -> None:
    for path, _ in source_paths(root):
        file_path = root / path
        lines = file_path.read_text(encoding="utf-8").splitlines()
        clean = [line for line in lines if not (is_rationale_comment_line(line) and MARKER in line)]
        if clean != lines:
            file_path.write_text("\n".join(clean) + "\n", encoding="utf-8")


def insertion_index(path: str, group: tuple[str, int], lines: list[str]) -> int:
    context, anchor = group
    if pathlib.Path(path).suffix.lower() in {".yml", ".yaml"}:
        return anchor if anchor else 0
    if pathlib.Path(path).suffix.lower() == ".html":
        if context == "css":
            return anchor
        return 1 if lines and lines[0].lstrip().lower().startswith("<!doctype") else 0
    if context in {"python", "bash", "powershell"} and lines and lines[0].startswith("#!"):
        return 1
    return 0


def write_markers(root: pathlib.Path) -> int:
    strip_markers(root)
    targets, _ = collect_targets(root)
    grouped: dict[tuple[str, tuple[str, int]], list[Target]] = collections.defaultdict(list)
    for target in targets:
        if target.path not in GENERATED_PATHS:
            grouped[(target.path, target.line.group)].append(target)
    by_path: dict[str, list[tuple[tuple[str, int], list[Target]]]] = collections.defaultdict(list)
    for (path, group), values in grouped.items():
        by_path[path].append((group, values))
    for path, groups in by_path.items():
        file_path = root / path
        lines = file_path.read_text(encoding="utf-8").splitlines()
        insertions: list[tuple[int, list[str]]] = []
        for group, values in groups:
            index = insertion_index(path, group, lines)
            indentation = ""
            if pathlib.Path(path).suffix.lower() in {".yml", ".yaml"} and group[1]:
                following = lines[index] if index < len(lines) else lines[index - 1]
                indentation = " " * leading_spaces(following)
            comments = [indentation + marker_text(group[0], target) for target in values]
            insertions.append((index, comments))
        for index, comments in sorted(insertions, key=lambda item: item[0], reverse=True):
            lines[index:index] = comments
        file_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return len(targets)


def audit(root: pathlib.Path) -> tuple[int, int, int, int, int]:
    targets, files = collect_targets(root)
    expected = collections.Counter((target.path, target.line.group, target.key) for target in targets)
    actual: collections.Counter[tuple[str, tuple[str, int], str]] = collections.Counter()
    generated_context = 0
    malformed = 0
    banned_prefixes = (
        "Executes the ",
        "Binds ",
        "Opens the ",
        "Closes the current scope",
        "Continues the ",
    )
    for path, infos in files.items():
        for info in infos:
            if not is_rationale_comment_line(info.text):
                continue
            match = MARKER_RE.search(info.text.strip())
            if (
                not match
                or not match.group(3).strip()
                or (match.group(1) == MARKER and match.group(3).startswith(banned_prefixes))
            ):
                malformed += 1
                continue
            marker_kind = match.group(1)
            if (marker_kind == GENERATED_MARKER) != (path in GENERATED_PATHS):
                malformed += 1
                continue
            scoped_key = (path, info.group, match.group(2))
            if marker_kind == GENERATED_MARKER and scoped_key not in expected:
                generated_context += 1
            else:
                actual[scoped_key] += 1
    uncovered = sum((expected - actual).values())
    extra = sum((actual - expected).values())
    duplicates = sum(max(0, count - expected[key]) for key, count in actual.items())
    return uncovered, extra, duplicates, malformed, generated_context


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true", help="regenerate source-local rationale ledgers")
    args = parser.parse_args()
    root = pathlib.Path(__file__).resolve().parents[1]
    try:
        run_git(root, "cat-file", "-e", f"{BASE}^{{commit}}")
        if args.write:
            count = write_markers(root)
            print(f"wrote {count} one-to-one added-line rationales relative to {BASE}")
        uncovered, extra, duplicates, malformed, generated_context = audit(root)
    except (OSError, RuntimeError, UnicodeError) as error:
        print(f"added-line rationale audit failed: {error}", file=sys.stderr)
        return 2
    print(
        f"added-line rationale audit: uncovered={uncovered} extra={extra} "
        f"duplicates={duplicates} malformed={malformed} generated_context={generated_context}"
    )
    return 1 if any((uncovered, extra, duplicates, malformed)) else 0


if __name__ == "__main__":
    raise SystemExit(main())
